import numpy as np

def solve(xs):
    xs = np.asanyarray(xs)
    if xs.size == 0:
        return np.array([0.0], dtype=np.float64)

    res = np.sum(xs[0::2].astype(np.float64)) - np.sum(xs[1::2].astype(np.float64))
    return np.array([res], dtype=np.float64)
