import numpy as np

def solve(labels):
    labels_arr = np.asanyarray(labels)
    if labels_arr.size == 0:
        return np.array([-99.], dtype=np.float64)

    unique_vals, counts = np.unique(labels_arr, return_counts=True)
    max_count = np.max(counts)
    winners = unique_vals[counts == max_count]

    if winners.size > 1:
        return np.array([-99.], dtype=np.float64)

    return np.array([winners[0]], dtype=np.float64)
