import numpy as np

def solve(labels):
    labels = np.asanyarray(labels)
    if labels.size == 0:
        return np.array([-88.0], dtype=np.float64)

    unique_vals, counts = np.unique(labels, return_counts=True)
    distinct_freqs = np.unique(counts)
    sorted_freqs = np.sort(distinct_freqs)[::-1]

    if len(sorted_freqs) < 2:
        return np.array([-88.0], dtype=np.float64)

    second_freq = sorted_freqs[1]
    labels_with_second_freq = unique_vals[counts == second_freq]

    if len(labels_with_second_freq) == 1:
        return np.array([labels_with_second_freq[0]], dtype=np.float64)
    else:
        return np.array([-88.0], dtype=np.float64)
```

